import time
import random
import math

def construct(n):
    if n <= 1:
        return "1"
    
    # Step 1: Generate the standard superpermutation for n-1
    # We need the sequence of (n-1)-permutations in the order they appear in the standard construction.
    # The standard construction builds S_n from S_{n-1} by taking the sequence of (n-1)-perms P_1, ..., P_k
    # and forming S_n = P_1 n P_1 P_2 n P_2 ... P_k n P_k (with overlaps).
    # However, to optimize, we treat the sequence of blocks B_1, ..., B_k as the variable.
    # The standard order is the one generated by the recursive step for n-1.
    
    # Let's generate the standard superpermutation for n-1 first to get the block sequence.
    # Actually, we can generate the block sequence directly using the recursive logic.
    # Let Blocks(m) be the list of blocks (tuples of length m) in the standard order for superpermutation of size m+1?
    # No, let's stick to the definition:
    # S_1 = "1"
    # S_2 = "121" -> Blocks for n=2 are [1, 2]? No.
    # Let's trace n=3.
    # S_2 = 1, 2, 1. Perms of 2: (1,2), (2,1).
    # Blocks from S_2: (1,2), (2,1).
    # S_3 = (1,2) 3 (1,2) (2,1) 3 (2,1) -> 1 2 3 1 2 2 1 3 2 1. Length 10.
    # Standard length for n=3 is 9? No, 1+2+3! = 9? 
    # 1 2 1 3 2 1 4 ... wait.
    # S_1 = 1
    # S_2 = 1 2 1 (Len 3). Perms: 12, 21.
    # S_3: Blocks from S_2 are 12, 21.
    #   12 3 12 21 3 21 -> 1 2 3 1 2 2 1 3 2 1. Len 10.
    #   Overlap: 12 3 12 | 21 3 21. End of first part 12, start of second 21. No overlap.
    #   Wait, 12 3 12 21 3 21.
    #   Is there a shorter one? 1 2 1 3 2 1 4 ... no.
    #   Standard S_3 is 1 2 1 3 2 1 4 ... no, that's n=4.
    #   S_3 is usually 1 2 1 3 2 1? No, 1 2 1 3 2 1 contains 121, 213, 132, 321. Missing 131? No, 131 is not a perm.
    #   Perms of 1,2,3: 123, 132, 213, 231, 312, 321.
    #   1 2 1 3 2 1:
    #   121 (no)
    #   213 (yes)
    #   132 (yes)
    #   321 (yes)
    #   Missing 123, 231, 312.
    #   
    #   Let's use the standard recursive definition properly.
    #   S_n is formed from S_{n-1}.
    #   Let P_1, ..., P_k be the (n-1)-permutations in the order they appear as windows in S_{n-1} that are "starts" of the blocks?
    #   Actually, the standard construction is:
    #   S_n = P_1 n P_1 P_2 n P_2 ... P_k n P_k
    #   where P_i are the permutations of n-1 in the order they appear in S_{n-1}.
    #   
    #   Let's get the list of blocks for n-1.
    #   For n=2, S_1 = "1". Blocks of length 1: [1].
    #   S_2 = 1 2 1. Blocks: 1, 2? No.
    #   The blocks are the (n-1)-perms.
    #   For S_2 (n=2), the (2-1)=1 perms are 1 and 2.
    #   Order in S_2: 1, 2, 1. The unique perms in order of appearance: 1, 2.
    #   So blocks for n=2 are [1], [2].
    #   S_2 constructed from blocks [1], [2] of S_1?
    #   S_1 = "1". Blocks of S_1 (len 1): [1].
    #   S_2 = 1 2 1.
    #   
    #   Let's define a function get_blocks(m) that returns the list of blocks (tuples of length m) 
    #   in the standard order for the superpermutation of size m+1? No, for size m?
    #   Let's say get_blocks(n) returns the list of (n-1)-tuples that form the blocks for S_n.
    #   
    #   Base case: n=1. S_1 = "1". Blocks for S_1? None? 
    #   Let's start from n=2.
    #   S_2 = "121". The (2-1)=1 perms are 1, 2.
    #   Order: 1 appears first, then 2.
    #   So blocks for n=2 are [(1,), (2,)].
    #   
    #   n=3. S_3 is built from blocks of n=2: (1,), (2,).
    #   Wait, the blocks for S_3 should be (3-1)=2-tuples.
    #   The blocks are the permutations of 1..2.
    #   In S_2="121", the 2-perms are 12, 21.
    #   Order: 12, 21.
    #   So blocks for n=3 are [(1,2), (2,1)].
    #   
    #   n=4. Blocks are 3-perms.
    #   We need the order of 3-perms in S_3.
    #   S_3 = 1 2 3 1 2 2 1 3 2 1.
    #   Windows of size 3:
    #   123, 231, 312, 122 (no), 221 (no), 213, 132, 321.
    #   Unique in order: 123, 231, 312, 213, 132, 321.
    #   So blocks for n=4 are these 6 tuples.
    
    def get_standard_blocks(n):
        if n == 1:
            return []
        if n == 2:
            return [(1,), (2,)]
        
        # Recursively get S_{n-1} to find the order of (n-1)-perms
        prev_word = construct(n-1)
        prev_list = [int(c) for c in prev_word]
        
        seen = set()
        blocks = []
        for i in range(len(prev_list) - (n-2)):
            window = tuple(prev_list[i:i+n-1])
            if len(set(window)) == n-1:
                if window not in seen:
                    seen.add(window)
                    blocks.append(window)
        return blocks

    blocks = get_standard_blocks(n)
    k = len(blocks)
    
    # Precompute overlap matrix
    # overlap[i][j] = max k such that blocks[i][-k:] == blocks[j][:k]
    # Note: blocks are tuples of length n-1.
    overlap = [[0] * k for _ in range(k)]
    for i in range(k):
        for j in range(k):
            if i == j:
                overlap[i][j] = n - 1 # Full overlap? No, suffix of A with prefix of A.
                # If A = (1,2,3), suffix (3) prefix (1) no.
                # But in the construction, we don't overlap a block with itself immediately in a way that saves n-1.
                # The structure is B_i n B_i. The next is B_j n B_j.
                # Overlap is between B_i (end of first segment) and B_j (start of next segment).
                # So we need suffix of B_i and prefix of B_j.
                pass
            
            max_k = n - 1
            found = 0
            for l in range(max_k, 0, -1):
                if blocks[i][-l:] == blocks[j][:l]:
                    found = l
                    break
            overlap[i][j] = found
            
    def calc_length(order):
        # order is a list of indices into blocks
        # Length = len(B_0) + 1 + len(B_0) + sum(1 + len(B_i) - overlap(B_{i-1}, B_i))
        # Wait, the first block contributes len(B_0) + 1 + len(B_0).
        # Subsequent blocks contribute 1 + len(B_i) - overlap(B_{i-1}, B_i).
        # Is this correct?
        # Segment i: B_i n B_i.
        # Segment i+1: B_{i+1} n B_{i+1}.
        # Concatenation: ... B_i n B_i B_{i+1} n B_{i+1} ...
        # Overlap is between suffix of B_i and prefix of B_{i+1}.
        # So added length for i+1 is 1 (for n) + len(B_{i+1}) - overlap.
        # But wait, the 'n' is in the middle.
        # Sequence: ... B_i, n, B_i, B_{i+1}, n, B_{i+1} ...
        # The overlap is between B_i (end of first part) and B_{i+1} (start of second part).
        # Yes.
        
        if not order:
            return 0
        total_len = len(blocks[order[0]]) + 1 + len(blocks[order[0]])
        for i in range(1, len(order)):
            prev_idx = order[i-1]
            curr_idx = order[i]
            total_len += 1 + len(blocks[curr_idx]) - overlap[prev_idx][curr_idx]
        return total_len

    # Initialize with standard order (0 to k-1)
    best_order = list(range(k))
    best_len = calc_length(best_order)
    
    start_time = time.time()
    time_limit = 115
    
    # VNS Parameters
    max_shake = 1000
    no_improve_count = 0
    
    def shake(order, strength):
        # Randomly perturb the order
        new_order = order[:]
        for _ in range(strength):
            i = random.randint(0, len(new_order) - 2)
            j = random.randint(i + 1, len(new_order) - 1)
            # Reverse segment
            new_order[i:j+1] = new_order[i:j+1][::-1]
        return new_order

    def local_search(order):
        # 2-Opt and Or-Opt
        improved = True
        while improved:
            improved = False
            # 2-Opt
            for i in range(len(order) - 1):
                for j in range(i + 1, len(order)):
                    new_order = order[:i] + order[i:j+1][::-1] + order[j+1:]
                    new_len = calc_length(new_order)
                    if new_len < best_len:
                        best_len = new_len
                        order = new_order
                        improved = True
            # Or-Opt (Move segment of size 1, 2, 3)
            for size in [1, 2, 3]:
                for i in range(len(order) - size):
                    segment = order[i:i+size]
                    for j in range(len(order) - size):
                        if i == j:
                            continue
                        # Remove segment
                        new_order = order[:i] + order[i+size:]
                        # Insert at j
                        # Adjust j if j > i
                        if j > i:
                            j -= size
                        new_order = new_order[:j] + segment + new_order[j:]
                        new_len = calc_length(new_order)
                        if new_len < best_len:
                            best_len = new_len
                            order = new_order
                            improved = True
        return order, best_len

    # Main VNS Loop
    current_order = best_order[:]
    current_len = best_len
    
    neighborhood_size = 1
    while time.time() - start_time < time_limit:
        # Local Search
        current_order, current_len = local_search(current_order)
        
        if current_len < best_len:
            best_len = current_len
            best_order = current_order
            neighborhood_size = 1
            no_improve_count = 0
        else:
            no_improve_count += 1
            if no_improve_count > 5:
                break
            
        # Shake
        if time.time() - start_time > time_limit:
            break
        current_order = shake(best_order, neighborhood_size)
        neighborhood_size += 1
        if neighborhood_size > 10:
            neighborhood_size = 1
            # Reset if we've gone through all neighborhoods
            if no_improve_count > 20:
                break

    # Reconstruct the word
    word = []
    for i, idx in enumerate(best_order):
        block = blocks[idx]
        if i == 0:
            word.extend(block)
            word.append(n)
            word.extend(block)
        else:
            prev_block = blocks[best_order[i-1]]
            # Calculate overlap
            max_k = n - 1
            found = 0
            for l in range(max_k, 0, -1):
                if prev_block[-l:] == block[:l]:
                    found = l
                    break
            # Add n and the rest of the block
            word.append(n)
            word.extend(block[found:])
            
    return "".join(map(str, word))
